1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { invoiceCreateData } from "./invoices";
9	
10	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
11	const MS_PER_AVG_MONTH = 30.44 * 86400_000;
12	
13	async function ownedServer(serverId: string) {
14	  const user = await requireUser();
15	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
16	  if (!server) throw new Error("Not found");
17	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
18	  return { user, server };
19	}
20	
21	async function queueJob(
22	  serverId: string,
23	  type:
24	    | "SNAPSHOT_CREATE"
25	    | "SNAPSHOT_DELETE"
26	    | "SNAPSHOT_ROLLBACK"
27	    | "BACKUP_CREATE"
28	    | "RESIZE"
29	    | "PASSWORD_RESET",
30	  payload?: Record<string, unknown>
31	): Promise<{ error?: string }> {
32	  const pending = await db.job.count({
33	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
34	  });
35	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
36	  await db.job.create({ data: { type, serverId, payload: payload as any } });
37	  return {};
38	}
39	
40	// ---------- Snapshots ----------
41	
42	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
43	  const { user, server } = await ownedServer(serverId);
44	  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
45	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
46	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
47	    return { error: "Server must be running or stopped." };
48	  }
49	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
50	  if (!res.error) {
51	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
52	    revalidatePath(`/dashboard/servers/${serverId}`);
53	  }
54	  return res;
55	}
56	
57	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
58	  const { user } = await ownedServer(serverId);
59	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name });
60	  if (!res.error) {
61	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${name}` } });
62	    revalidatePath(`/dashboard/servers/${serverId}`);
63	  }
64	  return res;
65	}
66	
67	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
68	  const { user } = await ownedServer(serverId);
69	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name });
70	  if (!res.error) {
71	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${name}` } });
72	    revalidatePath(`/dashboard/servers/${serverId}`);
73	  }
74	  return res;
75	}
76	
77	// ---------- Backups ----------
78	
79	export async function createBackup(serverId: string): Promise<{ error?: string }> {
80	  const { user, server } = await ownedServer(serverId);
81	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
82	    return { error: "Server must be running or stopped." };
83	  }
84	  const res = await queueJob(serverId, "BACKUP_CREATE");
85	  if (!res.error) {
86	    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
87	    revalidatePath(`/dashboard/servers/${serverId}`);
88	  }
89	  return res;
90	}
91	
92	// ---------- Resize ----------
93	
94	export async function resizeServer(serverId: string, planId: string): Promise<{ error?: string }> {
95	  const { user, server } = await ownedServer(serverId);
96	  const newPlan = await db.plan.findUnique({ where: { id: planId } });
97	  if (!newPlan?.active) return { error: "Plan not available." };
98	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
99	  if (newPlan.diskGB < server.plan.diskGB) {
100	    return { error: "Disk storage can only grow — choose a plan with equal or larger disk." };
101	  }
102	  if (newPlan.priceCents < server.plan.priceCents) {
103	    return { error: "Downgrades aren't self-service yet — please contact support." };
104	  }
105	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
106	
107	  // Prorate the upgrade over the ACTUAL remaining duration, not a fraction of a
108	  // single term. `renewNow` can stack expiresAt many terms into the future, so a
109	  // "fraction of one term" clamp let a customer who prepaid e.g. 13 months upgrade
110	  // for only ~1 term of the delta. Charge the monthly price difference for every
111	  // remaining month instead. Null expiresAt (free/admin servers) => 0.
112	  let prorateCents = 0;
113	  if (!server.isFree && server.expiresAt) {
114	    const now = Date.now();
115	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
116	    const monthlyDelta = newPlan.priceCents - server.plan.priceCents; // plan.priceCents is the monthly price
117	    prorateCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
118	    if (prorateCents > 0 && user.balanceCents < prorateCents) {
119	      return {
120	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term. Top up your wallet first.`,
121	      };
122	    }
123	  }
124	
125	  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
126	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
127	
128	  try {
129	    await db.$transaction(async (tx) => {
130	      if (prorateCents > 0) {
131	        await debitWallet(tx, server.userId, prorateCents);
132	        await tx.walletTransaction.create({
133	          data: { userId: server.userId, amountCents: -prorateCents, description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}` },
134	        });
135	        // PAID invoice for the proration charge (one per user-initiated resize).
136	        await tx.invoice.create({
137	          data: invoiceCreateData({
138	            userId: server.userId,
139	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
140	            status: "PAID",
141	            lineItems: [
142	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
143	            ],
144	          }),
145	        });
146	      }
147	      // Record the amount charged on the job so the worker's RESIZE handler can
148	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
149	      // resize terminally fails — money is committed here, before the job runs.
150	      // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
151	      await tx.job.create({
152	        data: { type: "RESIZE", serverId, payload: { planId, prorateCents, direction: "up" } as any },
153	      });
154	      await tx.auditLog.create({
155	        data: { userId: user.id, action: "server.resize", detail: `${serverId} -> ${newPlan.slug} prorate=${prorateCents}` },
156	      });
157	    });
158	  } catch (e) {
159	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
160	    throw e;
161	  }
162	  revalidatePath(`/dashboard/servers/${serverId}`);
163	  return {};
164	}
165	
166	// ---------- Root password reset ----------
167	
168	export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
169	  const { user, server } = await ownedServer(serverId);
170	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
171	    return { error: "Server must be running or stopped to reset its password." };
172	  }
173	  const res = await queueJob(serverId, "PASSWORD_RESET");
174	  if (!res.error) {
175	    await db.auditLog.create({
176	      data: { userId: user.id, action: "server.password_reset", detail: serverId },
177	    });
178	    revalidatePath(`/dashboard/servers/${serverId}`);
179	    revalidatePath(`/admin/servers/${serverId}`);
180	  }
181	  return res;
182	}
183	
184	// ---------- Port forwarding (firewall/networking) ----------
185	
186	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
187	const MAX_FORWARDS_PER_SERVER = 10;
188	
189	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
190	  const serverId = String(formData.get("serverId") ?? "");
191	  const { user, server } = await ownedServer(serverId);
192	  const parsed = z
193	    .object({
194	      guestPort: z.coerce.number().int().min(1).max(65535),
195	      protocol: z.enum(["tcp", "udp"]),
196	    })
197	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
198	  if (!parsed.success) return { error: "Invalid port." };
199	
200	  const count = await db.portForward.count({ where: { serverId } });
201	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
202	
203	  const used = new Set([
204	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
205	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
206	  ]);
207	  let publicPort = 0;
208	  for (let p = PF_MIN; p <= PF_MAX; p++) {
209	    if (!used.has(p)) { publicPort = p; break; }
210	  }
211	  if (!publicPort) return { error: "No public ports available." };
212	
213	  await db.portForward.create({
214	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
215	  });
216	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
217	  await db.auditLog.create({
218	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
219	  });
220	  revalidatePath(`/dashboard/servers/${serverId}`);
221	  return {};
222	}
223	
224	export async function deletePortForward(serverId: string, forwardId: string) {
225	  const { user } = await ownedServer(serverId);
226	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
227	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
228	  await db.auditLog.create({
229	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
230	  });
231	  revalidatePath(`/dashboard/servers/${serverId}`);
232	}
