64	/**
65	 * Credit a user's wallet for a completed Checkout session, idempotently.
66	 * Called from both the success-redirect confirm route (works without HTTPS)
67	 * and the webhook (belt-and-suspenders once HTTPS is available).
68	 * Returns true if a credit was applied this call.
69	 */
70	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
71	  const session = await stripe().checkout.sessions.retrieve(sessionId);
72	  const userId = session.metadata?.nxeonUserId;
73	  const cents = session.amount_total ?? 0;
74	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
75	
76	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
77	  // session id inside the description.
78	  const legacy = await db.walletTransaction.findFirst({
79	    where: { stripeSessionId: null, description: { contains: session.id } },
80	  });
81	  if (legacy) return false;
82	
83	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
84	  // read-then-write check. The confirm-redirect and the webhook can arrive
85	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
86	  // only the database can safely decide the winner. P2002 == already credited.
87	  try {
88	    await db.$transaction([
89	      db.walletTransaction.create({
90	        data: {
91	          userId,
92	          amountCents: cents,
93	          description: `Stripe payment (${session.id})`,
94	          stripeSessionId: session.id,
95	        },
96	      }),
97	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
98	      db.notification.create({
99	        data: {
100	          userId,
101	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
102	          href: "/dashboard/billing",
103	        },
104	      }),
105	      // PAID invoice for the top-up. Created in the SAME guarded transaction as
106	      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
107	      // the credit idempotent also prevents a duplicate invoice on replay.
108	      db.invoice.create({
109	        data: invoiceCreateData({
110	          userId,
111	          description: "Wallet top-up",
112	          status: "PAID",
113	          lineItems: [
114	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
115	          ],
116	        }),
117	      }),
118	    ]);
119	  } catch (e) {
120	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
121	    throw e;
122	  }
123	  // A funded wallet is the referred user's first paid action — reward both sides.
124	  try {
125	    const { maybeRewardReferral } = await import("./actions-growth");
126	    await maybeRewardReferral(userId);
127	  } catch { /* best-effort */ }
128	  try {
129	    const u = await db.user.findUnique({ where: { id: userId } });
130	    if (u) {
131	      const { sendMail, emails } = await import("./mailer");
132	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
133	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
134	    }
135	  } catch { /* best-effort */ }
136	  return true;
137	}
