4	export async function POST(req: NextRequest) {
5	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
6	    return NextResponse.json({ error: "not configured" }, { status: 400 });
7	  }
8	  const sig = req.headers.get("stripe-signature");
9	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
10	  const raw = await req.text();
11	
12	  let event;
13	  try {
14	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
15	  } catch {
16	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
17	  }
18	
19	  if (event.type === "checkout.session.completed") {
20	    const session = event.data.object as { id: string };
21	    await creditCheckoutSession(session.id);
22	  }
23	
24	  return NextResponse.json({ received: true });
25	}
