 * wallet pre-fund). Mirrors createOrderCheckout: the card is charged the full
 * shortfall-covering amount, credited to the wallet on confirm, and the resize
 * then spends it. Metadata carries enough to apply the resize server-side.
 */
export async function createResizeCheckout(
  user: { id: string; email: string },
  amountCents: number,
  resize: { serverId: string; planId: string; planName?: string },
): Promise<string | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `Nxeon VPS upgrade${resize.planName ? ` — ${resize.planName}` : ""}` },
